#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# #653: sets Resend up as production's one mail provider, end to end: the sending domain and the receive-only domain
# in Tokyo (tracking off), their DNS records in Cloudflare through scripts/cloudflare-record.ts, the one webhook on the
# worker's route, a sending-only API key for the sending domain, and the three Secret Manager secrets. Every stage reads
# before it writes, so a re-run changes nothing that is already right.
#
# A person supplies: a full-access Resend API key (RESEND_FULL_ACCESS_KEY in the environment, or at the hidden prompt),
# M1KU_CLOUDFLARE_API_TOKEN in the shell, a gcloud sign-in as a skyclause owner, and a yes at each write. Run it from
# anywhere in the repo after the production Terraform apply has made the three secrets and the worker. About 20 minutes
# plus Resend's DNS check, which usually takes up to 15 minutes.
#
# DNS names, values and MX priorities come from what Resend's Domains API returns, never from this file. The wizard
# touches no other record, so every SES record stays, except the MX at in. (replaced by Resend's) and the DMARC
# record at notices. (rewritten without its report address); the AWS teardown (#661) removes the rest.

PROJECT=skyclause
GCP_REGION=asia-southeast1
RESEND_API=https://api.resend.com
RESEND_REGION=ap-northeast-1
SENDING_DOMAIN=notices.skyclause.m1ku.tech
RECEIVING_DOMAIN=in.skyclause.m1ku.tech
DNS_ZONE=m1ku.tech
# The worker's one public route for every Resend webhook; the worker's code mounts the same path.
WEBHOOK_PATH=/resend/webhook
WEBHOOK_EVENTS_JSON='["email.delivered","email.bounced","email.complained","email.suppressed","email.received"]'
SENDING_KEY_NAME=skyclause-production-sending
# DMARC for notices. keeps p=quarantine but loses its rua: the SES rule that caught the reports goes, and nothing read them.
DMARC_NAME="_dmarc.$SENDING_DOMAIN"
DMARC_VALUE='v=DMARC1; p=quarantine'
SECRETS=(RESEND_RECEIVING_API_KEY RESEND_SENDING_API_KEY RESEND_WEBHOOK_SECRET)
TFVARS_FILE="${TFVARS_FILE:-infra/environments/production/terraform.tfvars}"
KEY_PATTERN='^re_[A-Za-z0-9_-]{8,}$'

API_STATUS=""
API_BODY=""
DOMAIN_ID=""

# ask_valid ask|ask_secret KEY "Prompt" REGEX "Hint" asks until the answer matches REGEX, and stops
# the wizard if input ends.
ask_valid() {
  local read_with="$1" key="$2" prompt="$3" pattern="$4" hint="$5"
  while true; do
    "$read_with" "$key" "$prompt" || { warn "No input, so stopping."; exit 1; }
    [[ "${!key}" =~ $pattern ]] && return 0
    warn "$hint"
  done
}

# on_exit names the stage a run stopped in, so no early exit is silent.
on_exit() {
  local status=$?
  (( status == 0 )) && return
  warn "Stopped in stage $_STAGE_INDEX/$TOTAL_STAGES (exit $status): the message above says why. Re-run to carry on; what is already right is left alone."
}

# resend METHOD PATH [JSON] calls Resend with FULL_ACCESS_KEY, which curl reads from stdin so it never shows in a process
# list, and sets API_STATUS and API_BODY. No request body holds a secret.
resend() {
  local method="$1" path="$2" body="${3:-}" raw
  local args=(-sS -K - -X "$method" -w $'\n%{http_code}')
  if [[ -n "$body" ]]; then args+=(-H 'Content-Type: application/json' --data "$body"); fi
  raw="$(printf 'header = "Authorization: Bearer %s"\nheader = "Accept: application/json"\n' "$FULL_ACCESS_KEY" |
    curl "${args[@]}" "$RESEND_API$path")" || return 1
  API_STATUS="${raw##*$'\n'}"
  API_BODY="${raw%$'\n'*}"
}

# resend_ok METHOD PATH [JSON] is resend, but stops the wizard unless Resend answers 2xx, showing Resend's own error.
resend_ok() {
  resend "$@" || { warn "Couldn't reach Resend: curl's error is above."; exit 1; }
  [[ "$API_STATUS" == 2* ]] || { warn "Resend answered HTTP $API_STATUS to $1 $2: $API_BODY"; exit 1; }
}

# json EXPR [ARG...] prints EXPR evaluated over API_BODY's JSON as data, as d, with the arguments as a. An answer it can't
# read fails with a warning on stderr, which stops the wizard wherever the result is assigned.
json() {
  printf '%s' "$API_BODY" |
    python3 -c 'import json, sys; d = json.load(sys.stdin); a = sys.argv[2:]; print(eval(sys.argv[1]))' "$@" 2>/dev/null ||
    { warn "Couldn't read $1 from Resend's answer." >&2; return 1; }
}

# resend_list PATH gets the first 100 entries of a list and stops if there are more, so no find below can miss one.
resend_list() {
  local more
  resend_ok GET "$1?limit=100"
  more="$(json "d.get('has_more') is True")"
  [[ "$more" != True ]] || { warn "Resend lists more than 100 entries at $1: look in its dashboard."; exit 1; }
}

# sending_key_is_live KEY succeeds when Resend, asked something only a full-access key may do, answers that KEY is restricted
# to sending: only a live sending-only key gets that answer, and a deleted or mistyped one gets "invalid".
sending_key_is_live() {
  ( FULL_ACCESS_KEY="$1"; resend GET "/domains?limit=1" && [[ "$API_STATUS" == 401 && "$API_BODY" == *restricted_api_key* ]] )
}

# add_version NAME VALUE adds VALUE as a new version of the Secret Manager secret NAME.
add_version() {
  printf '%s' "$2" | gcloud secrets versions add "$1" --project="$PROJECT" --data-file=- >/dev/null
  printf '  %s✓ stored%s %s in Secret Manager (%s)\n' "$GREEN" "$RESET" "$1" "$PROJECT"
}

# store_secret NAME VALUE adds VALUE as a new version of NAME unless the latest version holds it already. A latest version
# that holds something else is replaced only after a yes.
store_secret() {
  local name="$1" value="$2" current
  current="$(gcloud secrets versions access latest --secret="$name" --project="$PROJECT" 2>/dev/null || true)"
  if [[ "$current" == "$value" ]]; then
    printf '  %s✓ unchanged%s %s already holds this value\n' "$GREEN" "$RESET" "$name"
    return 0
  fi
  if [[ -n "$current" ]] && ! confirm "$name holds a different value. Add this one as a new version?"; then
    SKIPPED+=("$name: Secret Manager holds a value that differs from Resend's (gcloud secrets versions add $name)")
    return 0
  fi
  add_version "$name" "$value"
}

# ensure_domain NAME SENDING RECEIVING creates the domain in RESEND_REGION with tracking off unless it exists. An existing
# one gets its tracking and capabilities set to what is wanted when they differ; its region can't change. Sets DOMAIN_ID.
ensure_domain() {
  local name="$1" sending="$2" receiving="$3" row id region open click have_sending have_receiving caps
  caps="{\"sending\":\"$sending\",\"receiving\":\"$receiving\"}"
  resend_list /domains
  row="$(json "' '.join(str(v) for x in d['data'] if x['name'] == a[0] for v in (x['id'], x['region'], x['open_tracking'], x['click_tracking'], x['capabilities']['sending'], x['capabilities']['receiving']))" "$name")"
  if [[ -z "$row" ]]; then
    resend_ok POST /domains "{\"name\":\"$name\",\"region\":\"$RESEND_REGION\",\"open_tracking\":false,\"click_tracking\":false,\"capabilities\":$caps}"
    DOMAIN_ID="$(json "d['id']")"
    printf '  %s✓ created%s %s in %s (sending %s, receiving %s, tracking off)\n' "$GREEN" "$RESET" "$name" "$RESEND_REGION" "$sending" "$receiving"
    return 0
  fi
  read -r id region open click have_sending have_receiving <<<"$row"
  if [[ "$region" != "$RESEND_REGION" ]]; then
    warn "$name is in $region, not $RESEND_REGION, and Resend can't move a domain between regions: delete it in the dashboard, delete its old records in Cloudflare, and re-run."
    exit 1
  fi
  if [[ "$open" == False && "$click" == False && "$have_sending" == "$sending" && "$have_receiving" == "$receiving" ]]; then
    printf '  %s✓ unchanged%s %s is in %s (sending %s, receiving %s, tracking off)\n' "$GREEN" "$RESET" "$name" "$region" "$sending" "$receiving"
  else
    resend_ok PATCH "/domains/$id" "{\"open_tracking\":false,\"click_tracking\":false,\"capabilities\":$caps}"
    printf '  %s✓ updated%s %s: tracking off, sending %s, receiving %s\n' "$GREEN" "$RESET" "$name" "$sending" "$receiving"
  fi
  DOMAIN_ID="$id"
}

# records_of DOMAIN prints one TYPE<TAB>NAME<TAB>CONTENT line for each DNS record in API_BODY's domain that Resend has not
# verified yet. Type, value and MX priority are Resend's; the name is made whole under DOMAIN. Resend's documented names are
# relative to the DNS zone (send.subdomain); a whole name, "@" and a name relative to the domain are accepted too. The names
# print before anything is written, and the record script refuses any name outside skyclause.m1ku.tech.
records_of() {
  printf '%s' "$API_BODY" | python3 -c '
import json, sys
domain, zone = sys.argv[1:3]
inside = lambda n: n == domain or n.endswith("." + domain)
for r in json.load(sys.stdin)["records"]:
    if r["status"] == "verified":
        continue
    name = r["name"].lower().rstrip(".")
    if name in ("", "@"):
        full = domain
    elif inside(name):
        full = name
    elif inside(name + "." + zone):
        full = name + "." + zone
    else:
        full = name + "." + domain
    if r["type"] == "MX" and r.get("priority") is None:
        sys.exit("Resend gives the MX record %s no priority." % r["name"])
    print("\t".join((r["type"], full, "%s %s" % (r["priority"], r["value"]) if r["type"] == "MX" else r["value"])))
' "$1" "$DNS_ZONE"
}

# verify_domain NAME ID asks Resend to check NAME's records unless it is verified, then waits for it. It stops on failed,
# and offers to stop waiting every 10 minutes (Resend allows up to 72 hours).
verify_domain() {
  local name="$1" id="$2" status tries=0
  resend_ok GET "/domains/$id"
  status="$(json "d['status']")"
  if [[ "$status" != verified ]]; then
    resend_ok POST "/domains/$id/verify"
    say "Asked Resend to check $name."
  fi
  until [[ "$status" == verified ]]; do
    sleep 15
    resend_ok GET "/domains/$id"
    status="$(json "d['status']")"
    if [[ "$status" == failed || "$status" == partially_failed ]]; then
      warn "Resend marked $name $status. Its records: $(json "'; '.join('%s %s %s' % (r['type'], r['name'], r['status']) for r in d['records'])")"
      exit 1
    fi
    note "$name: $status"
    tries=$((tries + 1))
    if (( tries % 40 == 0 )) && ! confirm "$name is still $status after 10 minutes. Keep waiting?"; then
      exit 1
    fi
  done
  printf '  %s✓ verified%s %s\n' "$GREEN" "$RESET" "$name"
}

run_wizard() {

TOTAL_STAGES=8
# The key goes into a variable, not the environment, so no child process (gcloud, bun) inherits it.
FULL_ACCESS_KEY="${RESEND_FULL_ACCESS_KEY:-}"
unset RESEND_FULL_ACCESS_KEY
trap on_exit EXIT
cd "$(dirname "${BASH_SOURCE[0]}")/../.."
# Not the root .env, which Bun loads in local development. Nothing this wizard handles is saved to it.
[[ "$ENV_FILE" == .env ]] && ENV_FILE=infra/wizards/.env

banner "Resend: domains, DNS, webhook, API keys and secrets"

stage "Check tools and access"
for tool in curl python3 gcloud bun; do
  command -v "$tool" >/dev/null 2>&1 || { warn "$tool is missing: install it and re-run"; exit 1; }
done
if [[ -z "${M1KU_CLOUDFLARE_API_TOKEN:-}" ]]; then
  warn "M1KU_CLOUDFLARE_API_TOKEN isn't set in this shell: export it and re-run"
  exit 1
fi
say "gcloud is signed in as ${BOLD}$(gcloud config get-value account 2>/dev/null)${RESET}."
for name in "${SECRETS[@]}"; do
  gcloud secrets describe "$name" --project="$PROJECT" >/dev/null ||
    { warn "Secret Manager has no $name in $PROJECT: the production Terraform apply makes it."; exit 1; }
done
say "The three secrets exist in $PROJECT."
WORKER_URL="$(gcloud run services describe worker --region="$GCP_REGION" --project="$PROJECT" --format='value(status.url)')"
WORKER_URL="${WORKER_URL%/}"
[[ "$WORKER_URL" == https://* ]] || { warn "Cloud Run didn't give the worker's https URL (got '$WORKER_URL'): the production Terraform apply makes the worker."; exit 1; }
say "The worker answers at $WORKER_URL."
pause

stage "Resend: the full-access API key"
if [[ -n "$FULL_ACCESS_KEY" ]]; then
  say "Using the key in RESEND_FULL_ACCESS_KEY."
else
  open_url "https://resend.com/api-keys"
  step "Create an API key with permission Full access, and copy it (Resend shows it once)."
  ask_valid ask_secret FULL_ACCESS_KEY "Paste the full-access key (hidden, never saved to disk):" "$KEY_PATTERN" \
    "Paste the whole key: it starts with re_."
fi
if [[ ! "$FULL_ACCESS_KEY" =~ $KEY_PATTERN ]]; then
  warn "That doesn't look like a Resend API key (it starts with re_)."
  exit 1
fi
resend GET "/domains?limit=100" || { warn "Couldn't reach Resend: curl's error is above."; exit 1; }
if [[ "$API_STATUS" == 401 && "$API_BODY" == *restricted_api_key* ]]; then
  warn "That key can only send mail. Give the wizard a key with permission Full access."
  exit 1
fi
[[ "$API_STATUS" == 2* ]] || { warn "Resend answered HTTP $API_STATUS: $API_BODY"; exit 1; }
printf '  %s✓ accepted%s: Resend lets this key list domains.\n' "$GREEN" "$RESET"
other_domains="$(json "', '.join(x['name'] for x in d['data'] if x['name'] not in a)" "$SENDING_DOMAIN" "$RECEIVING_DOMAIN")"
if [[ -n "$other_domains" ]]; then
  say "This Resend account also holds: $other_domains."
  confirm "Is it Skyclause's account?" || { say "Nothing changed."; exit 1; }
fi
note "This key becomes RESEND_RECEIVING_API_KEY in stage 8: the worker reads received mail with it."
pause

stage "Resend: the two domains"
say "Sending: $SENDING_DOMAIN. Receive-only: $RECEIVING_DOMAIN. Both in $RESEND_REGION (Tokyo), open and click tracking off."
ensure_domain "$SENDING_DOMAIN" enabled disabled
SENDING_ID="$DOMAIN_ID"
ensure_domain "$RECEIVING_DOMAIN" disabled enabled
RECEIVING_ID="$DOMAIN_ID"
pause

stage "Cloudflare: the DNS records"
say "Resend's records sit beside SES's under other names, so SES keeps working. Only the MX at $RECEIVING_DOMAIN is replaced."
note "Names, values and priorities are what Resend returned just now. Every SES record stays except that MX and the DMARC"
note "report address; the AWS teardown (#661) removes the rest."
# DMARC goes first: once the MX moves, a report still addressed to dmarc@in. would reach Resend and count against its quota.
want=("TXT"$'\t'"$DMARC_NAME"$'\t'"$DMARC_VALUE")
for pair in "$SENDING_DOMAIN:$SENDING_ID" "$RECEIVING_DOMAIN:$RECEIVING_ID"; do
  resend_ok GET "/domains/${pair#*:}"
  lines="$(records_of "${pair%%:*}")"
  while IFS= read -r line; do
    if [[ -n "$line" ]]; then want+=("$line"); fi
  done <<<"$lines"
done
types=(); names=(); contents=(); actions=()
pending=0
replaced_mx=""
action_pattern='would be (created|updated|unchanged)'
for ((i = 0; i < ${#want[@]}; i++)); do
  IFS=$'\t' read -r type name content <<<"${want[$i]}"
  case "$type" in
    A | AAAA | CNAME | TXT | MX) ;;
    *)
      warn "$type $name can't be written by scripts/cloudflare-record.ts."
      SKIPPED+=("Cloudflare: enter the $type record $name with content '$content' by hand")
      continue
      ;;
  esac
  out="$(bun scripts/cloudflare-record.ts --dry-run "$type" "$name" "$content" 2>&1)" || { warn "$out"; exit 1; }
  [[ "$out" =~ $action_pattern ]] || { warn "Unexpected answer from the record script: $out"; exit 1; }
  action="${BASH_REMATCH[1]}"
  if [[ "$action" == updated && "$type $name" != "MX $RECEIVING_DOMAIN" && "$name" != "$DMARC_NAME" ]]; then
    warn "Cloudflare already has a $type record at $name with other content. This wizard replaces only the MX at $RECEIVING_DOMAIN and the DMARC record, so nothing was written."
    exit 1
  fi
  types+=("$type"); names+=("$name"); contents+=("$content"); actions+=("$action")
  if [[ "$action" != unchanged ]]; then pending=$((pending + 1)); fi
  if [[ "$type" == MX && "$action" == updated ]]; then replaced_mx="$name"; fi
  shown="$content"
  if (( ${#shown} > 60 )); then shown="${shown:0:60}…"; fi
  printf '  %-9s %-5s %s → %s\n' "$action" "$type" "$name" "$shown"
done
if (( pending == 0 )); then
  note "Every record is already in Cloudflare."
else
  if [[ -n "$replaced_mx" ]]; then
    warn "This replaces the MX at $replaced_mx, which sends inbound mail to SES today. Until the Resend-backed worker is deployed,"
    warn "mail to $replaced_mx (Crowd replies and evidence requests) reaches nobody."
  fi
  confirm "Write the $pending change(s) to the m1ku.tech zone (DNS only, comment 'owner: skyclause')?" || { say "Nothing written."; exit 1; }
  for ((i = 0; i < ${#actions[@]}; i++)); do
    if [[ "${actions[$i]}" != unchanged ]]; then bun scripts/cloudflare-record.ts "${types[$i]}" "${names[$i]}" "${contents[$i]}"; fi
  done
fi
pause

stage "Resend: wait for verification"
verify_domain "$SENDING_DOMAIN" "$SENDING_ID"
verify_domain "$RECEIVING_DOMAIN" "$RECEIVING_ID"
pause

stage "Resend: the webhook"
WEBHOOK_URL="$WORKER_URL$WEBHOOK_PATH"
say "One endpoint takes every delivery, bounce, complaint, suppression and received-mail event: $WEBHOOK_URL"
resend_list /webhooks
hook_id="$(json "next((w['id'] for w in d['data'] if w['endpoint'] == a[0]), '')" "$WEBHOOK_URL")"
if [[ -z "$hook_id" ]]; then
  resend_ok POST /webhooks "{\"endpoint\":\"$WEBHOOK_URL\",\"events\":$WEBHOOK_EVENTS_JSON}"
  hook_secret="$(json "d['signing_secret']")"
  printf '  %s✓ created%s the webhook with its five events\n' "$GREEN" "$RESET"
else
  resend_ok GET "/webhooks/$hook_id"
  hook_secret="$(json "d['signing_secret']")"
  hook_right="$(json "d.get('status') == 'enabled' and sorted(d.get('events') or []) == sorted(json.loads(a[0]))" "$WEBHOOK_EVENTS_JSON")"
  if [[ "$hook_right" == True ]]; then
    printf '  %s✓ unchanged%s the webhook is enabled with its five events\n' "$GREEN" "$RESET"
  else
    resend_ok PATCH "/webhooks/$hook_id" "{\"events\":$WEBHOOK_EVENTS_JSON,\"status\":\"enabled\"}"
    printf '  %s✓ updated%s the webhook: enabled, with its five events\n' "$GREEN" "$RESET"
  fi
fi
store_secret RESEND_WEBHOOK_SECRET "$hook_secret"
unset hook_secret
pause

stage "Resend: the sending-only API key"
say "RESEND_SENDING_API_KEY is a key that can only send, and only from $SENDING_DOMAIN: web and worker hold it."
resend_list /api-keys
key_id="$(json "next((k['id'] for k in d['data'] if k['name'] == a[0]), '')" "$SENDING_KEY_NAME")"
stored_key="$(gcloud secrets versions access latest --secret=RESEND_SENDING_API_KEY --project="$PROJECT" 2>/dev/null || true)"
if [[ -n "$stored_key" ]] && sending_key_is_live "$stored_key"; then
  printf '  %s✓ unchanged%s RESEND_SENDING_API_KEY holds a live sending-only key\n' "$GREEN" "$RESET"
else
  if [[ -n "$key_id" ]]; then
    warn "Resend has a key named $SENDING_KEY_NAME, but RESEND_SENDING_API_KEY doesn't hold a live token for it, and Resend shows a token only once."
    confirm "Delete the key in Resend and make a new one?" || { say "Nothing changed."; exit 1; }
    resend_ok DELETE "/api-keys/$key_id"
  elif [[ -n "$stored_key" ]]; then
    warn "RESEND_SENDING_API_KEY holds a token Resend doesn't accept, and Resend has no key named $SENDING_KEY_NAME."
    confirm "Make a new key and add it as a new version?" || { say "Nothing changed."; exit 1; }
  fi
  resend_ok POST /api-keys "{\"name\":\"$SENDING_KEY_NAME\",\"permission\":\"sending_access\",\"domain_id\":\"$SENDING_ID\"}"
  sending_key="$(json "d['token']")"
  add_version RESEND_SENDING_API_KEY "$sending_key"
  unset sending_key
fi
unset stored_key
pause

stage "Secret Manager: the receiving key, and what to commit"
say "The full-access key from stage 2 is RESEND_RECEIVING_API_KEY: only the worker mounts it."
store_secret RESEND_RECEIVING_API_KEY "$FULL_ACCESS_KEY"
unset FULL_ACCESS_KEY
if listed="$(python3 -c '
import re, sys
match = re.search(r"^supplied_secrets\s*=\s*\[([^]]*)\]", open(sys.argv[1]).read(), re.M)
if not match:
    sys.exit(1)
listed = set(re.findall(r"\"([A-Z0-9_]+)\"", match.group(1)))
if not set(sys.argv[2:]) <= listed:
    print("supplied_secrets = [%s]" % ", ".join("\"%s\"" % n for n in sorted(listed | set(sys.argv[2:]))))
' "$TFVARS_FILE" "${SECRETS[@]}")"; then
  if [[ -z "$listed" ]]; then
    note "supplied_secrets in $TFVARS_FILE already lists all three, so the next Terraform apply turns mail on."
  else
    say "Commit this line in $TFVARS_FILE in a pull request:"
    say "  $listed"
    warn "Mail stays off until that line is committed and Terraform has applied it: until then no service gets a sender address,"
    warn "the inbound domain or a Resend secret, so nothing is sent or received. That includes the time since this change deployed."
  fi
else
  say "Add ${SECRETS[*]} to supplied_secrets in $TFVARS_FILE. Mail stays off until Terraform has applied it."
fi
note "After the apply, check a real send, a bounce and an inbound reply."

finish
}

run_wizard "$@"; exit
